  const Technique({
    required this.key,
    required this.title,
    required this.region,
    required this.history,
    required this.whyItCosts,
  });

  /// Matches Product.technique, lowercased, as stored in Postgres.
  final String key;
  final String title;
  final String region;
  final T history;
  final String whyItCosts;
}

